            mechanism: "价键理论认为，在苯分子中，每个碳原子以 sp² 杂化轨道与相邻碳原子的 sp² 杂化轨道相互重叠，构成六个等同的 C—C σ 键。同时，每个碳原子以 sp² 杂化轨道，分别与一个氢原子的 1s 轨道相互重叠，构成六个相同的 C—H σ 键。这六个碳原子和六个氢原子是共平面的。每一个碳原子剩下的一个 p 轨道，其对称轴垂直于这个平面，彼此相互平行，并于两侧相互重叠，形成一个闭合的 π 轨道。",
            conditions: "苯分子是对称的，这种结构特点不能用经典的价键结构式的描绘方法表达出来。通常还是采用 Kekulé 结构式来表示。",
