            mechanism: "由于分子间氢键缔合作用，除甲酰胺外，其他伯酰胺均为固体；当氮原子上的氢原子被取代后，分子间氢键缔合减少或消失，酰胺的熔点和沸点显著降低。",
            conditions: "酰氯和酸酐不溶于水，低级的遇水分解，酯在水中溶解度较小。低级酰胺溶于水，N,N-二甲基甲酰胺和 N,N-二甲基乙酰胺可与水混溶，它们是很好的极性非质子溶剂。",
            keywords: ["物理性质", "沸点", "熔点", "溶解度"],
