            formula: "",
            mechanism: "亲核酰基取代机理：亲核试剂进攻羰基碳，形成四面体中间体，然后离去基团离开。离去基团越容易离开，活性越高。",
            conditions: "水解：酰卤常温，酸酐加热，酯需酸碱催化，酰胺需强酸/强碱长时间回流。",
