            conditions: "在室温下，液态乙酰乙酸乙酯平衡混合物中约含 7.5% 的烯醇式异构体和 92.5% 的酮式异构体。",
            keywords: ["乙酰乙酸乙酯", "三乙", "酮式", "烯醇式"],
