            content: "氨分子中的氢原子部分或全部被烃基取代后的化合物，统称为胺。胺是一类最重要的含氮有机化合物，广泛存在于生物界。",
            formula: "",
            mechanism: "按照氮原子连接的烃基数目不同，可把胺分为伯（1°）、仲（2°）和叔（3°）胺。胺的分类与伯、仲、叔醇或伯、仲、叔卤代烃有本质的不同。",
            conditions: "当 R, R' 和 R'' 都是脂肪族烃基时，为脂肪胺；而当 R, R' 和 R'' 中至少有一个是芳基时，则为芳香族胺，简称芳胺。按照分子中氨基（—NH₂）的数目，胺也可分为一元胺、二元胺和多元胺。",
