            content: "与氨相似，胺分子中的氮原子为 sp³ 杂化，它以三个 sp³ 杂化轨道分别与碳原子的 sp³ 杂化轨道或氢原子的 1s 轨道形成三个 σ 键，未共用电子对则占据另一个 sp³ 杂化轨道。",
            formula: "",
            mechanism: "氨（或胺）分子呈棱锥形结构，C—N 单键和/或 N—H 单键间的键角接近 109.5°。当胺的氮原子上连有三个不同的原子或基团时，它是手性分子，未共用电子对可看成氮原子上连接的第四个“取代基”。",
            conditions: "氨、甲胺和三甲胺的结构如图 15-1 所示。",
