            formula: "\\chemfig{R-NH_2} + H_2O \\rightleftharpoons \\chemfig{R-NH_3^+} + OH^-",
            mechanism: "胺氮上有孤对电子，能接受质子显碱性。脂肪胺烷基给电子，使氮上电子云密度增加，碱性增强。芳香胺氮孤对电子与苯环共轭，碱性减弱。",
