            formula: "",
            mechanism: "激动药（agonist）：与受体结合后产生药理效应，如肾上腺素激动β受体。完全激动药：亲和力和内在活性都强，如吗啡。拮抗药（antagonist）：与受体结合但不产生效应，如普萘洛尔阻断β受体，纳洛酮阻断阿片受体。部分激动药：内在活性不强，如喷他佐辛，低剂量激动，高剂量拮抗。竞争性拮抗药：与激动药竞争相同受体，增加激动药剂量可对抗。非竞争性拮抗药：与受体结合后改变受体结构，激动药无法对抗。",
