            mechanism: "GPCR（G 蛋白偶联受体）：通过 G 蛋白介导信号转导，是最大的受体超家族，如肾上腺素受体、M 胆碱受体、阿片受体。离子通道受体（配体门控离子通道）：配体结合后直接开启离子通道，如 N 胆碱受体、GABA_A 受体。酶活性受体（酪氨酸激酶受体）：受体本身具有酶活性，如胰岛素受体、表皮生长因子受体。核受体（细胞核激素受体）：位于细胞核内，调节基因转录，如糖皮质激素受体、甲状腺激素受体。",
