            mechanism: "缩宫素（催产素）：直接兴奋子宫平滑肌，小剂量加强子宫节律性收缩，大剂量引起强直性收缩。麦角新碱：选择性兴奋子宫平滑肌，作用强而持久，易引起强直性收缩。前列腺素（地诺前列酮）：对妊娠各期子宫均有兴奋作用。",
            conditions: "缩宫素：催产、引产、产后止血。麦角新碱：产后子宫出血、子宫复旧不全。前列腺素：足月引产、中期引产。注意：缩宫素用于催产时需严格掌握剂量，避免子宫强直性收缩导致胎儿窒息或子宫破裂。",
