            mechanism: "竞争性阻断H1受体，对抗组胺引起的毛细血管扩张、通透性增加、平滑肌收缩。第一代：苯海拉明、异丙嗪、氯苯那敏，中枢抑制作用强，有嗜睡副作用。第二代：氯雷他定、西替利嗪，中枢抑制作用弱，无嗜睡，长效。",
            conditions: "苯海拉明：荨麻疹、过敏性鼻炎、晕动病。氯雷他定：过敏性鼻炎、荨麻疹（每日一次，无嗜睡）。异丙嗪：人工冬眠、镇静催眠。不良反应：第一代嗜睡、口干；第二代心脏毒性（阿司咪唑）。",
