            conditions: "必需氨基酸：人体不能合成，必须从食物摄取（8种）：缬氨酸、亮氨酸、异亮氨酸、苯丙氨酸、甲硫氨酸、色氨酸、苏氨酸、赖氨酸。",
            keywords: ["氨基酸", "蛋白质", "20种氨基酸", "必需氨基酸"],
